:root {
    --layout-max-width: 1600px;
    --layout-news-columns: repeat(3, 1fr);
    --layout-card-gap: 4rem;
    --layout-card-direction: column;
    --layout-animation-style: kinetic-slot-cylinder;
}

#news-container {
    max-width: var(--layout-max-width);
    margin: 10rem auto;
    padding: 0 4rem;
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    perspective: 2000px;
}

/* カラムごとのオフセットによるパララックス効果 */
#news-container > .news-card:nth-child(3n+2) {
    margin-top: 8rem;
}

#news-container > .news-card:nth-child(3n+3) {
    margin-top: 16rem;
}

.news-card {
    position: relative;
    transform-style: preserve-3d;
    /* Scroll-driven Animation 設定 */
    view-timeline-name: --card-reveal;
    view-timeline-axis: block;
    animation: reveal-and-rotate both linear;
    animation-timeline: --card-reveal;
    animation-range: entry 0% cover 50%;
}

@keyframes reveal-and-rotate {
    from {
        opacity: 0;
        transform: perspective(1000px) rotateX(45deg) translateZ(-200px) translateY(100px);
        filter: blur(10px) brightness(0.5);
    }
    to {
        opacity: 1;
        transform: perspective(1000px) rotateX(0deg) translateZ(0) translateY(0);
        filter: blur(0px) brightness(1);
    }
}

.news-card-body {
    background: linear-gradient(135deg, rgba(var(--morph-bg-secondary-rgb), 0.8), rgba(var(--morph-bg-secondary-rgb), 0.4));
